<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="page-heading"><div><p class="eyebrow">Transactions</p><h1>Sales History</h1></div><a class="button" href="<?= site_url('sales/new') ?>">Record Sale</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>Customer</th><th>Staff</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php if(!$sales): ?><tr><td colspan="6" class="empty">No sales recorded.</td></tr><?php endif; ?><?php foreach($sales as $s): ?><tr><td><?= esc(date('M j, Y g:i A',strtotime($s['created_at']))) ?></td><td><?= esc($s['product_name']) ?></td><td><?= esc($s['customer_name']??'Walk-in') ?></td><td><?= esc($s['staff_name']) ?></td><td><?= esc($s['quantity']) ?></td><td>₱<?= number_format((float)$s['total_price'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><?= $this->endSection() ?>
